-- V69 CPF Enterprise Cache / Async File Job (Oracle)
CREATE TABLE cpf_cache_invalidation_event (
    event_id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    event_key VARCHAR2(100 CHAR) NOT NULL UNIQUE,
    tenant_id VARCHAR2(80 CHAR) NOT NULL,
    namespace_cd VARCHAR2(80 CHAR) NOT NULL,
    cache_key VARCHAR2(512 CHAR) DEFAULT '' NOT NULL,
    event_version NUMBER(19) DEFAULT 0 NOT NULL,
    reason VARCHAR2(500 CHAR) NOT NULL,
    requested_by VARCHAR2(100 CHAR) NOT NULL,
    created_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE INDEX ix_cpf_cache_inv_scope ON cpf_cache_invalidation_event(tenant_id, namespace_cd, event_id);

CREATE TABLE cpf_cache_invalidation_checkpoint (
    consumer_id VARCHAR2(120 CHAR) PRIMARY KEY,
    last_event_id NUMBER(19) DEFAULT 0 NOT NULL,
    updated_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP NOT NULL
);
